export interface WorldDivision { n: string; a?: string }

/** عدد التقسيمات الإدارية المدعومة (للعرض في الواجهة) */
export const WORLD_DIVISIONS_COUNT = 4870;

/** تقسيمات دولة بكودها (ISO-3166 alpha-2) — مصفوفة فارغة عند عدم وجودها */
export function divisionsOf(code: string | null | undefined): WorldDivision[] {
  const list = WORLD_STATES[String(code ?? "").trim().toUpperCase()];
  if (!list) return [];
  return list.map((d) => (d.length > 1 ? { n: d[0], a: d[1] } : { n: d[0] }));
}

/** تسمية التقسيم بلغة الواجهة: العربية إن توفرت، وإلا الإنجليزية */
export function divisionLabel(d: WorldDivision | null | undefined, lang: string): string {
  if (!d) return "";
  return lang === "ar" && d.a ? d.a : d.n;
}

/** إيجاد تقسيم داخل دولة بمطابقة الاسم العربي أو الإنجليزي (للاستيراد) */
export function findDivision(code: string | null | undefined, name: string | null | undefined): WorldDivision | null {
  const q = String(name ?? "").trim();
  if (!q) return null;
  for (const d of divisionsOf(code)) {
    if (d.n === q || d.a === q) return d;
  }
  return null;
}
